'use strict';
function detectPartition(heartbeats, now, timeoutMs) {
  const unreachable = [];
  for (const [node, lastSeen] of Object.entries(heartbeats)) {
    if (now - lastSeen > timeoutMs) unreachable.push(node);
  }
  return { partitioned: unreachable.length > 0, unreachable };
}
module.exports = { detectPartition };

'use strict';
function grantLease(holder, ttlMs, now) {
  return { holder, grantedAt: now, expiresAt: now + ttlMs };
}
function isLeaseValid(lease, now) {
  return Boolean(lease) && lease.expiresAt > now;
}
module.exports = { grantLease, isLeaseValid };

'use strict';
function createBroker() {
  const subscribers = {};
  return {
    subscribe(topic, fn) { (subscribers[topic] = subscribers[topic] || []).push(fn); },
    publish(topic, msg) { (subscribers[topic] || []).forEach((fn) => fn(msg)); },
  };
}
module.exports = { createBroker };

'use strict';
function replicaLag(primaryOffset, replicaOffset) {
  return Math.max(0, primaryOffset - replicaOffset);
}
function isCaughtUp(primaryOffset, replicaOffset, slack) {
  return replicaLag(primaryOffset, replicaOffset) <= (slack || 0);
}
module.exports = { replicaLag, isCaughtUp };

'use strict';
function createRegistry() {
  const services = {};
  return {
    register(name, addr) { (services[name] = services[name] || []).push(addr); },
    deregister(name, addr) {
      services[name] = (services[name] || []).filter((a) => a !== addr);
    },
    lookup(name) { return (services[name] || []).slice(); },
  };
}
module.exports = { createRegistry };
